{"file_path": "choosers/over-constraining-push.yml", "content": "# This pack's own push rule, in its own choosers/ folder, compiled from the spec's Choosers section.
# The method never asks a met period what it had to spare, because this flow states no margin for a
# met period: it asks for less than it believes is possible and lets the flow say by how much it was
# wrong. `over-constrain-and-read-the-violation.md` is the knowledge behind the move.
id: over-constraining-push
version: '1'
title: Over-constrain the clock period by one step and read the violation

parameter:
  name: stepNs
  unit: ns

reads:
  period: { type: clock_period, unit: ns }
  slack: { type: setup_wns, unit: ns }

decide:
  - when: { constraint: PASS, goal: PASS }
    goalMet: true
  - when: { constraint: PASS }
    next:
      periodNs: { sum: [period, { neg: stepNs }] }
  - when: { constraint: FAIL }
    next:
      periodNs: { sum: [period, { abs: slack }, { neg: stepNs }] }
"}
